// CPython's CJK codecs (Modules/cjkcodecs): the multibyte decoders, the
// ISO-2022-JP family and HZ, with CPython's own tables (generated by
// tools/fixtures/generate_codecs.py, so the output doesn't depend on the
// runtime's TextDecoder) and the same error ranges and reasons.

import {
  ASCII_LIMIT,
  decodeError,
  type ErrorContext,
  TextBuilder,
} from './py-codecs-base';
import {
  PY_EUC_KR_JAMO,
  PY_GB18030_RANGES,
  PY_MULTIBYTE_TABLES,
  type PyMultibyteTable,
} from './py-codecs-data';

const ILLEGAL = 'illegal multibyte sequence';
const INCOMPLETE = 'incomplete multibyte sequence';

const FIRST_TRAIL = 0x40;
const INVALID = -1;
const MULTI = -2;
const INVALID_CHAR = ' ';
const INHERIT_CHAR = '=';
const MULTI_CHAR = '￿';

/** A codec's table, expanded for lookups by integer. */
interface MultibyteTable {
  /** Code point of bytes 0x80-0xFF alone, or {@link INVALID}. */
  readonly single: Int32Array;
  /** By `(lead - 0x80) << 8 | trail`: code point, INVALID or MULTI. */
  readonly pairs: Int32Array;
  /** EUC-JP's SS3 sequences, by `(second - 0x80) << 8 | third`. */
  readonly triples: Int32Array | null;
  /** Text of the MULTI entries, by `lead << 8 | trail`. */
  readonly multi: ReadonlyMap<number, string>;
}

const TABLES = new Map<string, MultibyteTable>();

function fillRows(
  target: Int32Array,
  rows: Readonly<Record<string, string>>,
  multi: Map<number, string>,
  extra: Readonly<Record<string, string>> | undefined,
  hasBase: boolean,
): void {
  for (const [leadHex, row] of Object.entries(rows)) {
    const lead = Number.parseInt(leadHex, 16);
    let trail = FIRST_TRAIL;
    for (const char of row) {
      const index = ((lead - 0x80) << 8) | trail;
      if (char === INVALID_CHAR) {
        target[index] = INVALID;
      } else if (char === MULTI_CHAR) {
        target[index] = MULTI;
        const key = (lead << 8) | trail;
        multi.set(key, extra?.[key.toString(16).padStart(4, '0')] ?? '');
      } else if (char !== INHERIT_CHAR || !hasBase) {
        target[index] = char.codePointAt(0) ?? INVALID;
      }
      trail += 1;
    }
  }
}

function buildTable(codec: string): MultibyteTable {
  const raw: PyMultibyteTable | undefined = PY_MULTIBYTE_TABLES[codec];
  if (raw === undefined) {
    throw new Error(`no multibyte table for ${codec}`);
  }
  const base = raw.base === undefined ? undefined : multibyteTable(raw.base);
  const single = new Int32Array(ASCII_LIMIT).fill(INVALID);
  const pairs = new Int32Array(ASCII_LIMIT << 8).fill(INVALID);
  const multi = new Map<number, string>(base?.multi);
  if (base !== undefined) {
    single.set(base.single);
    pairs.set(base.pairs);
  }
  let index = 0;
  for (const char of raw.single) {
    if (char === INVALID_CHAR) {
      single[index] = INVALID;
    } else if (char !== INHERIT_CHAR) {
      single[index] = char.codePointAt(0) ?? INVALID;
    }
    index += 1;
  }
  fillRows(pairs, raw.rows, multi, raw.multi, base !== undefined);
  let triples: Int32Array | null = null;
  if (raw.triples !== undefined) {
    triples = new Int32Array(ASCII_LIMIT << 8).fill(INVALID);
    fillRows(triples, raw.triples, multi, raw.multi, false);
  }
  if (codec === 'cp949') {
    fillUnifiedHangul(pairs, multibyteTable('euc_kr'));
  }
  return { single, pairs, triples, multi };
}

function multibyteTable(codec: string): MultibyteTable {
  let table = TABLES.get(codec);
  if (table === undefined) {
    table = buildTable(codec);
    TABLES.set(codec, table);
  }
  return table;
}

const HANGUL_FIRST = 0xac00;
const HANGUL_LAST = 0xd7a3;

// The Unified Hangul Code area of cp949 holds, in order, the Hangul
// syllables that KS X 1001 (euc_kr) lacks; the generator checks this.
function fillUnifiedHangul(pairs: Int32Array, eucKr: MultibyteTable): void {
  const known = new Set<number>(eucKr.pairs);
  const syllables: number[] = [];
  for (let code = HANGUL_FIRST; code <= HANGUL_LAST; code += 1) {
    if (!known.has(code)) {
      syllables.push(code);
    }
  }
  let next = 0;
  for (let lead = 0x81; lead <= 0xc6; lead += 1) {
    const lastTrail = lead <= 0xa0 ? 0xfe : 0xa0;
    for (let trail = 0x41; trail <= lastTrail; trail += 1) {
      const inArea =
        trail <= 0x5a || (trail >= 0x61 && trail <= 0x7a) || trail >= 0x81;
      if (inArea) {
        pairs[((lead - 0x80) << 8) | trail] = syllables[next] ?? INVALID;
        next += 1;
      }
    }
  }
}

/** The table entry for `lead`, `trail` (both bytes). */
function lookupPair(
  table: MultibyteTable,
  lead: number,
  trail: number,
): number {
  return lead < ASCII_LIMIT
    ? INVALID
    : (table.pairs[((lead - 0x80) << 8) | trail] ?? INVALID);
}

function emit(
  output: TextBuilder,
  table: MultibyteTable,
  code: number,
  key: number,
): void {
  if (code === MULTI) {
    output.text(table.multi.get(key) ?? '');
  } else {
    output.codePoint(code);
  }
}

/** Copies the run of ASCII bytes at `start`; returns where it ends. */
function copyAscii(
  bytes: Uint8Array,
  start: number,
  output: TextBuilder,
): number {
  let end = start;
  while (end < bytes.length && (bytes[end] ?? 0) < ASCII_LIMIT) {
    end += 1;
  }
  output.latin1(bytes.subarray(start, end));
  return end;
}

const EUC_JP_SS3 = 0x8f;
const EUC_KR_JAMO_LEAD = 0xa4;
const EUC_KR_JAMO_FILLER = 0xd4;
const EUC_KR_SEQUENCE = 8;
const SYLLABLES_PER_CHOSEONG = 588;
const SYLLABLES_PER_JUNGSEONG = 28;

// KS X 1001:1998 Annex 3 make-up sequence (A4D4 A4xx A4yy A4zz) at `index`:
// the syllable, or null when invalid.
function eucKrJamo(bytes: Uint8Array, index: number): number | null {
  if (
    bytes[index + 2] !== EUC_KR_JAMO_LEAD ||
    bytes[index + 4] !== EUC_KR_JAMO_LEAD ||
    bytes[index + 6] !== EUC_KR_JAMO_LEAD
  ) {
    return null;
  }
  const choByte = bytes[index + 3] ?? 0;
  const jungByte = bytes[index + 5] ?? 0;
  const jongByte = bytes[index + 7] ?? 0;
  const cho =
    choByte >= 0xa1 && choByte <= 0xbe
      ? (PY_EUC_KR_JAMO.choseong[choByte - 0xa1] ?? -1)
      : -1;
  const jung = jungByte >= 0xbf && jungByte <= 0xd3 ? jungByte - 0xbf : -1;
  let jong = -1;
  if (jongByte === EUC_KR_JAMO_FILLER) {
    jong = 0;
  } else if (jongByte >= 0xa1 && jongByte <= 0xbe) {
    jong = PY_EUC_KR_JAMO.jongseong[jongByte - 0xa1] ?? -1;
  }
  if (cho < 0 || jung < 0 || jong < 0) {
    return null;
  }
  return (
    HANGUL_FIRST +
    cho * SYLLABLES_PER_CHOSEONG +
    jung * SYLLABLES_PER_JUNGSEONG +
    jong
  );
}

const GB18030_BMP_SEQUENCES = 39_420;
const GB18030_FIRST_SUPPLEMENTARY_LEAD = 15;

// GB18030 four-byte sequence at `index` (second byte already 0x30-0x39):
// the code point, or null when invalid.
function gb18030FourBytes(bytes: Uint8Array, index: number): number | null {
  const b1 = bytes[index] ?? 0;
  const b3 = bytes[index + 2] ?? 0;
  const b4 = bytes[index + 3] ?? 0;
  if (
    b1 < 0x81 ||
    b1 > 0xfe ||
    b3 < 0x81 ||
    b3 > 0xfe ||
    b4 < 0x30 ||
    b4 > 0x39
  ) {
    return null;
  }
  const c1 = b1 - 0x81;
  const c2 = (bytes[index + 1] ?? 0) - 0x30;
  const c3 = b3 - 0x81;
  const c4 = b4 - 0x30;
  if (c1 < 4) {
    const linear = (c1 * 10 + c2) * 1260 + c3 * 10 + c4;
    if (linear >= GB18030_BMP_SEQUENCES) {
      return null;
    }
    // Last range starting at or before `linear`.
    let low = 0;
    let high = PY_GB18030_RANGES.length - 1;
    while (low < high) {
      const middle = (low + high + 1) >> 1;
      if ((PY_GB18030_RANGES[middle]?.[0] ?? 0) <= linear) {
        low = middle;
      } else {
        high = middle - 1;
      }
    }
    const [start = 0, first = 0] = PY_GB18030_RANGES[low] ?? [];
    return first + linear - start;
  }
  if (c1 >= GB18030_FIRST_SUPPLEMENTARY_LEAD) {
    const code =
      0x10000 +
      ((c1 - GB18030_FIRST_SUPPLEMENTARY_LEAD) * 10 + c2) * 1260 +
      c3 * 10 +
      c4;
    return code <= 0x10ffff ? code : null;
  }
  return null;
}

/**
 * Bytes a lead byte needs (counting itself), as CPython's decoder checks
 * them with `REQUIRE_INBUF`.
 */
function sequenceWidth(
  codec: string,
  bytes: Uint8Array,
  index: number,
): number {
  const byte = bytes[index] ?? 0;
  if (codec === 'euc_jp' && byte === EUC_JP_SS3) {
    return 3;
  }
  if (codec === 'gb18030') {
    const second = bytes[index + 1];
    if (second !== undefined && second >= 0x30 && second <= 0x39) {
      return 4;
    }
  }
  if (
    codec === 'euc_kr' &&
    byte === EUC_KR_JAMO_LEAD &&
    bytes[index + 1] === EUC_KR_JAMO_FILLER
  ) {
    return EUC_KR_SEQUENCE;
  }
  return 2;
}

// shift_jis rejects these lead bytes without looking at the next byte.
function isShiftJisLead(byte: number): boolean {
  return (byte >= 0x81 && byte <= 0x9f) || (byte >= 0xe0 && byte <= 0xea);
}

/** Python's table-driven CJK codecs (big5, gbk, euc_kr, shift_jis...). */
function decodeMultibyte(context: ErrorContext): string {
  const { bytes, codec } = context;
  const table = multibyteTable(codec);
  const output = new TextBuilder();
  let index = 0;
  while (index < bytes.length) {
    const byte = bytes[index] ?? 0;
    if (byte < ASCII_LIMIT) {
      index = copyAscii(bytes, index, output);
      continue;
    }
    const single = table.single[byte - ASCII_LIMIT] ?? INVALID;
    if (single !== INVALID) {
      output.codePoint(single);
      index += 1;
      continue;
    }
    if (codec === 'shift_jis' && !isShiftJisLead(byte)) {
      index = decodeError(output, context, index, index + 1, ILLEGAL);
      continue;
    }
    const width = sequenceWidth(codec, bytes, index);
    if (index + width > bytes.length) {
      index = decodeError(output, context, index, bytes.length, INCOMPLETE);
      continue;
    }
    const trail = bytes[index + 1] ?? 0;
    let code: number | null = null;
    if (width === 2) {
      code = lookupPair(table, byte, trail);
    } else if (width === 3) {
      const third = bytes[index + 2] ?? 0;
      code =
        trail < ASCII_LIMIT
          ? INVALID
          : (table.triples?.[((trail - 0x80) << 8) | third] ?? INVALID);
    } else if (width === 4) {
      code = gb18030FourBytes(bytes, index);
    } else {
      code = eucKrJamo(bytes, index);
    }
    if (code === null || code === INVALID) {
      index = decodeError(output, context, index, index + 1, ILLEGAL);
      continue;
    }
    emit(output, table, code, (byte << 8) | trail);
    index += width;
  }
  return output.toString();
}

// ISO-2022 (CPython's _codecs_iso2022.c), for the JIS X 0208/0212/0201
// variants. Character sets are named by their final byte, with 0x80 added
// for double-byte sets.
const ESC = 0x1b;
const LF = 0x0a;
const SPACE = 0x20;
const MAX_ESCAPE_LENGTH = 16;
const DBCS = 0x80;
const CHARSET_ASCII = 0x42; // 'B'
const JISX0208 = 0x42 | DBCS;
const JISX0208_OLD = 0x40 | DBCS; // '@'
const JISX0212 = 0x44 | DBCS; // 'D'
const JISX0201_ROMAN = 0x4a; // 'J'
const JISX0201_KATAKANA = 0x49; // 'I'

const ISO2022_CHARSETS: Readonly<Record<string, readonly number[]>> = {
  iso2022_jp: [JISX0208, JISX0201_ROMAN, JISX0208_OLD],
  iso2022_jp_1: [JISX0208, JISX0212, JISX0201_ROMAN, JISX0208_OLD],
  iso2022_jp_ext: [
    JISX0208,
    JISX0212,
    JISX0201_ROMAN,
    JISX0201_KATAKANA,
    JISX0208_OLD,
  ],
};

function isEscapeEnd(byte: number): boolean {
  return (byte >= 0x41 && byte <= 0x5a) || byte === 0x40;
}

function isIso2022Escape(byte: number | undefined): boolean {
  // ( ) $ . &
  return (
    byte === 0x28 ||
    byte === 0x29 ||
    byte === 0x24 ||
    byte === 0x2e ||
    byte === 0x26
  );
}

interface Iso2022State {
  /** G0 and G1 designations. */
  g: [number, number];
}

/** `iso2022processesc()`: 0 on success, -1 for too few bytes, or the error length. */
function processEscape(
  bytes: Uint8Array,
  index: number,
  charsets: readonly number[],
  state: Iso2022State,
): { result: number; length: number } {
  const left = bytes.length - index;
  let length = 0;
  let position = 1;
  for (; position < MAX_ESCAPE_LENGTH; position += 1) {
    if (position >= left) {
      return { result: -1, length: 0 };
    }
    const byte = bytes[index + position] ?? 0;
    if (isEscapeEnd(byte)) {
      length = position + 1;
      break;
    }
    // USE_JISX0208_EXT: skip "&@" (JIS X 0208-1990 announcer).
    if (
      position + 1 < left &&
      byte === 0x26 &&
      bytes[index + position + 1] === 0x40
    ) {
      position += 2;
    }
  }
  if (position >= MAX_ESCAPE_LENGTH) {
    return { result: 1, length: 0 };
  }
  const second = bytes[index + 1] ?? 0;
  const third = bytes[index + 2] ?? 0;
  let charset: number;
  let designation: 0 | 1;
  switch (length) {
    case 3:
      if (second === 0x24) {
        charset = third | DBCS;
        designation = 0;
      } else if (second === 0x28 || second === 0x29) {
        charset = third;
        designation = second === 0x28 ? 0 : 1;
      } else {
        return { result: 3, length: 0 };
      }
      break;
    case 4: {
      if (second !== 0x24) {
        return { result: 4, length: 0 };
      }
      charset = (bytes[index + 3] ?? 0) | DBCS;
      if (third === 0x28 || third === 0x29) {
        designation = third === 0x28 ? 0 : 1;
      } else {
        return { result: 4, length: 0 };
      }
      break;
    }
    case 6:
      if (
        bytes[index + 3] === ESC &&
        bytes[index + 4] === 0x24 &&
        bytes[index + 5] === 0x42
      ) {
        charset = JISX0208;
        designation = 0;
      } else {
        return { result: 6, length: 0 };
      }
      break;
    default:
      return { result: length, length: 0 };
  }
  if (charset !== CHARSET_ASCII && !charsets.includes(charset)) {
    return { result: length, length: 0 };
  }
  state.g[designation] = charset;
  return { result: 0, length };
}

function inJisRange(byte: number): boolean {
  return byte >= 0x21 && byte <= 0x7e;
}

// One character of a designated set: the code point, or INVALID.
function iso2022Char(
  charset: number,
  first: number,
  second: number,
  eucJp: MultibyteTable,
): number {
  switch (charset) {
    case JISX0201_ROMAN:
      if (first === 0x5c) {
        return 0xa5;
      }
      if (first === 0x7e) {
        return 0x203e;
      }
      return first;
    case JISX0201_KATAKANA:
      return first >= 0x21 && first <= 0x5f ? 0xff40 + first : INVALID;
    case JISX0212:
      return inJisRange(first) && inJisRange(second)
        ? (eucJp.triples?.[(first << 8) | (second | DBCS)] ?? INVALID)
        : INVALID;
    default:
      // JIS X 0208 (both designations), as EUC-JP stores it.
      return inJisRange(first) && inJisRange(second)
        ? lookupPair(eucJp, first | DBCS, second | DBCS)
        : INVALID;
  }
}

function decodeIso2022(context: ErrorContext): string {
  const { bytes } = context;
  const charsets = ISO2022_CHARSETS[context.codec] ?? [];
  const eucJp = multibyteTable('euc_jp');
  const state: Iso2022State = { g: [CHARSET_ASCII, CHARSET_ASCII] };
  const output = new TextBuilder();
  let escapeThroughout = false;
  let index = 0;
  const fail = (length: number, reason = ILLEGAL): void => {
    const end = reason === INCOMPLETE ? bytes.length : index + length;
    index = decodeError(output, context, index, end, reason);
  };
  while (index < bytes.length) {
    const byte = bytes[index] ?? 0;
    if (escapeThroughout) {
      // Not an ISO-2022 escape: copied through up to its final byte.
      output.unit(byte);
      index += 1;
      if (isEscapeEnd(byte)) {
        escapeThroughout = false;
      }
      continue;
    }
    if (byte === ESC) {
      if (index + 1 >= bytes.length) {
        fail(0, INCOMPLETE);
        continue;
      }
      if (isIso2022Escape(bytes[index + 1])) {
        const { result, length } = processEscape(bytes, index, charsets, state);
        if (result === -1) {
          fail(0, INCOMPLETE);
        } else if (result > 0) {
          fail(result);
        } else {
          index += length;
        }
        continue;
      }
      output.unit(ESC);
      escapeThroughout = true;
      index += 1;
      continue;
    }
    if (byte < SPACE || byte === LF) {
      // C0 controls pass through (SI/SO too: these variants don't shift).
      output.unit(byte);
      index += 1;
      continue;
    }
    if (byte >= ASCII_LIMIT) {
      fail(1);
      continue;
    }
    const charset = state.g[0];
    if (charset === CHARSET_ASCII) {
      index = copyIso2022Ascii(bytes, index, output);
      continue;
    }
    const width = charset & DBCS ? 2 : 1;
    if (index + width > bytes.length) {
      fail(0, INCOMPLETE);
      continue;
    }
    const code = iso2022Char(charset, byte, bytes[index + 1] ?? 0, eucJp);
    if (code === INVALID) {
      fail(width);
      continue;
    }
    output.codePoint(code);
    index += width;
  }
  return output.toString();
}

// Printable ASCII in the ASCII set (stops at ESC and controls).
function copyIso2022Ascii(
  bytes: Uint8Array,
  start: number,
  output: TextBuilder,
): number {
  let end = start;
  while (end < bytes.length) {
    const byte = bytes[end] ?? 0;
    if (byte < SPACE || byte >= ASCII_LIMIT) {
      break;
    }
    end += 1;
  }
  output.latin1(bytes.subarray(start, end));
  return end;
}

const TILDE = 0x7e;

/** CPython's `hz` codec (GB2312 between `~{` and `~}`). */
function decodeHz(context: ErrorContext): string {
  const { bytes } = context;
  const gb2312 = multibyteTable('gb2312');
  const output = new TextBuilder();
  let gbMode = false;
  let index = 0;
  while (index < bytes.length) {
    const byte = bytes[index] ?? 0;
    if (byte === TILDE) {
      const next = bytes[index + 1];
      if (next === undefined) {
        index = decodeError(output, context, index, bytes.length, INCOMPLETE);
        continue;
      }
      if (next === TILDE && !gbMode) {
        output.unit(TILDE);
      } else if (next === 0x7b && !gbMode) {
        gbMode = true;
      } else if (next === LF && !gbMode) {
        // line continuation
      } else if (next === 0x7d && gbMode) {
        gbMode = false;
      } else {
        index = decodeError(output, context, index, index + 1, ILLEGAL);
        continue;
      }
      index += 2;
      continue;
    }
    if (byte >= ASCII_LIMIT) {
      index = decodeError(output, context, index, index + 1, ILLEGAL);
      continue;
    }
    if (!gbMode) {
      output.unit(byte);
      index += 1;
      continue;
    }
    const second = bytes[index + 1];
    if (second === undefined) {
      index = decodeError(output, context, index, bytes.length, INCOMPLETE);
      continue;
    }
    const code =
      inJisRange(byte) && inJisRange(second)
        ? lookupPair(gb2312, byte | DBCS, second | DBCS)
        : INVALID;
    if (code === INVALID) {
      index = decodeError(output, context, index, index + 1, ILLEGAL);
      continue;
    }
    output.codePoint(code);
    index += 2;
  }
  return output.toString();
}

/**
 * Decode with one of CPython's CJK codecs, or return undefined when the
 * codec isn't one of them.
 */
export function decodeCjk(context: ErrorContext): string | undefined {
  if (Object.hasOwn(PY_MULTIBYTE_TABLES, context.codec)) {
    return decodeMultibyte(context);
  }
  if (Object.hasOwn(ISO2022_CHARSETS, context.codec)) {
    return decodeIso2022(context);
  }
  if (context.codec === 'hz') {
    return decodeHz(context);
  }
  return undefined;
}
